let notes = [];let deletedNotes = [];let highestZ = 10;let selectedNoteId = null;let dragState = null;let resizeState = null;let autoSaveInterval;let timerIntervals ={};let reminderCheckInterval;const MAX_HISTORY = 50;let undoStack = [];let redoStack = [];function pushHistory(){const snapshot = JSON.stringify({notes,deletedNotes,highestZ});undoStack.push(snapshot);if (undoStack.length > MAX_HISTORY){undoStack.shift()}redoStack = []}function undo(){if (undoStack.length === 0) return false;const current = JSON.stringify({notes,deletedNotes,highestZ});redoStack.push(current);const previous = JSON.parse(undoStack.pop());notes = previous.notes;deletedNotes = previous.deletedNotes;highestZ = previous.highestZ;renderAllNotes();saveToStorage();showToast('Undo');return true}function redo(){if (redoStack.length === 0) return false;const current = JSON.stringify({notes,deletedNotes,highestZ});undoStack.push(current);const next = JSON.parse(redoStack.pop());notes = next.notes;deletedNotes = next.deletedNotes;highestZ = next.highestZ;renderAllNotes();saveToStorage();showToast('Redo');return true}function isDarkMode(){return localStorage.getItem('deskboard-darkmode') === 'true'}function toggleDarkMode(){const isDark = !isDarkMode();localStorage.setItem('deskboard-darkmode',isDark);applyDarkMode(isDark);showToast(isDark ? 'Dark mode on':'Dark mode off')}function applyDarkMode(isDark){document.documentElement.classList.toggle('dark-mode',isDark);const btn = document.querySelector('.dark-mode-btn');if (btn){btn.innerHTML = isDark ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>'}}const STICKY_COLORS = ['#fef3c7','#dbeafe','#fce7f3','#dcfce7','#ffedd5','#f3e8ff'];const QUOTES = [ "The only way to do great work is to love what you do.","Stay hungry,stay foolish.","Done is better than perfect.","Simplicity is the ultimate sophistication.","Creativity is intelligence having fun.","Focus on being productive instead of busy.","Your future is created by what you do today." ];const TIMER_PRESETS = [{label:'25m',seconds:25 * 60},{label:'15m',seconds:15 * 60},{label:'5m',seconds:5 * 60},{label:'1m',seconds:60}];const REMINDER_PRESETS = [{label:'💧 Water (30m)',minutes:30,icon:'💧'},{label:'👁️ Eyes (20m)',minutes:20,icon:'👁️'},{label:'🚶 Stretch (45m)',minutes:45,icon:'🚶'},{label:'🍎 Snack (2h)',minutes:120,icon:'🍎'},{label:'☕ Break (1h)',minutes:60,icon:'☕'}];
const board = document.getElementById('board');const emptyHint = document.getElementById('emptyHint');const toast = document.getElementById('toast');const searchInput = document.getElementById('searchInput');const recycleBin = document.getElementById('recycleBin');const binCount = document.getElementById('binCount');
function generateId(){return Math.random().toString(36).substr(2,9)}function getBoardRect(){return document.getElementById('board').getBoundingClientRect()}function showToast(msg){const toast = document.getElementById('toast');toast.textContent = msg;toast.classList.add('show');setTimeout(() => toast.classList.remove('show'),2500)}function formatTime(seconds){const m = Math.floor(seconds / 60);const s = seconds % 60;return `${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}`}function escapeHtml(text){const div = document.createElement('div');div.textContent = text;return div.innerHTML}function getTimeAgo(timestamp){const seconds = Math.floor((Date.now() - timestamp) / 1000);if (seconds < 60) return 'just now';if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;return `${Math.floor(seconds / 86400)}d ago`}
let audioCtx = null;function getAudioContext(){if (!audioCtx){audioCtx = new (window.AudioContext || window.webkitAudioContext)()}return audioCtx}function playPinSound(){const ctx = getAudioContext();if (ctx.state === 'suspended') ctx.resume();const osc = ctx.createOscillator();const gain = ctx.createGain();osc.type = 'triangle';osc.frequency.setValueAtTime(800,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(300,ctx.currentTime + 0.1);gain.gain.setValueAtTime(0.15,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime + 0.1);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime + 0.1)}function playDeleteSound(){const ctx = getAudioContext();if (ctx.state === 'suspended') ctx.resume();const osc = ctx.createOscillator();const gain = ctx.createGain();osc.type = 'sine';osc.frequency.setValueAtTime(400,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(100,ctx.currentTime + 0.15);gain.gain.setValueAtTime(0.1,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime + 0.15);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime + 0.15)}function playTimerCompleteSound(){const ctx = getAudioContext();if (ctx.state === 'suspended') ctx.resume();const notes_chime = [523.25,659.25,783.99,1046.50];notes_chime.forEach((freq,i) =>{const osc = ctx.createOscillator();const gain = ctx.createGain();osc.type = 'sine';osc.frequency.setValueAtTime(freq,ctx.currentTime + i * 0.15);gain.gain.setValueAtTime(0.2,ctx.currentTime + i * 0.15);gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime + i * 0.15 + 0.5);osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime + i * 0.15);osc.stop(ctx.currentTime + i * 0.15 + 0.5)})}function playReminderAlertSound(){const ctx = getAudioContext();if (ctx.state === 'suspended') ctx.resume();[0,0.15,0.3].forEach((delay) =>{const osc = ctx.createOscillator();const gain = ctx.createGain();osc.type = 'square';osc.frequency.setValueAtTime(880,ctx.currentTime + delay);gain.gain.setValueAtTime(0.1,ctx.currentTime + delay);gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime + delay + 0.1);osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime + delay);osc.stop(ctx.currentTime + delay + 0.1)})}
function updateClock(){const now = new Date();const time = now.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});const date = now.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});document.getElementById('clock').textContent = `${time}· ${date}`}
function getTimerState(note){return note.timerState ||{totalSeconds:25 * 60,remainingSeconds:25 * 60,isRunning:false,isPaused:false,isFinished:false}}function updateTimerDisplay(noteId){const note = notes.find(n => n.id === noteId);if (!note || note.type !== 'timer') return;const state = getTimerState(note);const el = document.getElementById(noteId);if (!el) return;const timeText = el.querySelector('.timer-time-text');const circle = el.querySelector('.timer-progress-circle');const status = el.querySelector('.timer-status');const widget = el.querySelector('.timer-widget');if (timeText) timeText.textContent = formatTime(state.remainingSeconds);if (circle){const circumference = 2 * Math.PI * 70;const progress = state.totalSeconds > 0 ? (state.remainingSeconds / state.totalSeconds):0;circle.style.strokeDashoffset = circumference * (1 - progress)}if (widget){widget.classList.remove('timer-running','timer-paused','timer-finished');if (state.isFinished) widget.classList.add('timer-finished');else if (state.isRunning) widget.classList.add('timer-running');else if (state.isPaused) widget.classList.add('timer-paused')}if (status){if (state.isFinished) status.textContent = "Time's up!";else if (state.isRunning) status.textContent = 'Focusing...';else if (state.isPaused) status.textContent = 'Paused';else status.textContent = 'Ready'}const playBtn = el.querySelector('.timer-play-btn');if (playBtn){playBtn.innerHTML = state.isRunning ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>':'<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>'}}function startTimer(noteId){const note = notes.find(n => n.id === noteId);if (!note || note.type !== 'timer') return;const state = getTimerState(note);if (state.isFinished){state.remainingSeconds = state.totalSeconds;state.isFinished = false}if (state.isRunning){state.isRunning = false;state.isPaused = true;clearInterval(timerIntervals[noteId]);delete timerIntervals[noteId]}else{state.isRunning = true;state.isPaused = false;timerIntervals[noteId] = setInterval(() =>{const currentNote = notes.find(n => n.id === noteId);if (!currentNote) return;const currentState = getTimerState(currentNote);currentState.remainingSeconds--;if (currentState.remainingSeconds <= 0){currentState.remainingSeconds = 0;currentState.isRunning = false;currentState.isFinished = true;clearInterval(timerIntervals[noteId]);delete timerIntervals[noteId];playTimerCompleteSound();showToast('⏰ Timer finished! Click to reset.');const el = document.getElementById(noteId);if (el){el.classList.add('timer-finished');note.zIndex = ++highestZ;el.style.zIndex = note.zIndex}}currentNote.timerState = currentState;updateTimerDisplay(noteId);saveToStorage()},1000)}note.timerState = state;updateTimerDisplay(noteId);saveToStorage()}function resetTimer(noteId){const note = notes.find(n => n.id === noteId);if (!note || note.type !== 'timer') return;clearInterval(timerIntervals[noteId]);delete timerIntervals[noteId];const state = getTimerState(note);state.remainingSeconds = state.totalSeconds;state.isRunning = false;state.isPaused = false;state.isFinished = false;note.timerState = state;updateTimerDisplay(noteId);saveToStorage()}function setTimerPreset(noteId,seconds){const note = notes.find(n => n.id === noteId);if (!note || note.type !== 'timer') return;clearInterval(timerIntervals[noteId]);delete timerIntervals[noteId];note.timerState ={totalSeconds:seconds,remainingSeconds:seconds,isRunning:false,isPaused:false,isFinished:false};updateTimerDisplay(noteId);saveToStorage()}
function getReminderState(note){if (!note.reminderState){return{title:'',intervalMinutes:0,lastAcknowledged:Date.now(),isBlinking:false,nextTrigger:Date.now() + 365 * 24 * 60 * 60 * 1000,acknowledgeHistory:[]}}return note.reminderState}function configureReminder(noteId){const note = notes.find(n => n.id === noteId);if (!note || note.type !== 'reminder') return;const titleInput = document.getElementById(`reminder-title-${noteId}`);const intervalInput = document.getElementById(`reminder-interval-${noteId}`);const customInput = document.getElementById(`reminder-custom-${noteId}`);const rawTitle = titleInput?.value?.trim();const title = rawTitle ? rawTitle:'Reminder';let minutes = parseInt(intervalInput?.value,10) || 30;if (intervalInput?.value === 'custom'){minutes = parseInt(customInput?.value,10) || 30}const now = Date.now();note.reminderState ={title:title,intervalMinutes:minutes,lastAcknowledged:now,isBlinking:false,nextTrigger:now + minutes * 60 * 1000,acknowledgeHistory:[now]};note.content = title;note.color = '#fef3c7';saveToStorage();renderNote(note);showToast(`Reminder set:every ${minutes}min`);playPinSound()}function acknowledgeReminder(noteId){const note = notes.find(n => n.id === noteId);if (!note || note.type !== 'reminder') return;const now = Date.now();const history = note.reminderState?.acknowledgeHistory || [];const triggerCount = history.length;const intervalMinutes = note.reminderState?.intervalMinutes || 30;const title = note.reminderState?.title || 'Reminder';note.reminderState ={title:title,intervalMinutes:intervalMinutes,lastAcknowledged:now,isBlinking:false,nextTrigger:now + intervalMinutes * 60 * 1000,acknowledgeHistory:[...history,now]};const el = document.getElementById(noteId);if (el){el.classList.remove('blinking')}saveToStorage();renderNote(note);showToast(`Reminder acknowledged ✓ (triggered ${triggerCount + 1}x)`);playPinSound()}function checkReminders(){const now = Date.now();notes.forEach(note =>{if (note.type !== 'reminder') return;const state = getReminderState(note);if (state.intervalMinutes === 0 || state.isBlinking) return;if (now >= state.nextTrigger){const history = note.reminderState?.acknowledgeHistory || [];note.reminderState ={title:state.title,intervalMinutes:state.intervalMinutes,lastAcknowledged:now,isBlinking:true,nextTrigger:now,acknowledgeHistory:[...history]};const el = document.getElementById(note.id);if (el){el.classList.add('blinking');note.zIndex = ++highestZ;el.style.zIndex = note.zIndex}playReminderAlertSound();showToast(`🔔 ${state.title}! Click to acknowledge.`);saveToStorage()}})}document.addEventListener('change',e =>{if (e.target.id && e.target.id.startsWith('reminder-interval-')){const noteId = e.target.id.replace('reminder-interval-','');handleReminderIntervalChange(e.target,noteId)}});function handleReminderIntervalChange(selectEl,noteId){const customInput = document.getElementById(`reminder-custom-${noteId}`);if (customInput){if (selectEl.value === 'custom'){customInput.style.setProperty('display','block','important');customInput.focus()}else{customInput.style.display = 'none'}}}
function saveToStorage(){const boardId = getCurrentBoardId();const data ={notes,deletedNotes,highestZ,timestamp:Date.now()};try{localStorage.setItem(`deskboard-data-${boardId}`,JSON.stringify(data))}catch (e){if (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_FILE_CORRUPTED'){showToast('Storage full! Clear some notes or bin.');console.error('Storage quota exceeded:',e)}else{showToast('Failed to save. Check console.');console.error('Storage error:',e)}}}function loadFromStorage(){const boardId = getCurrentBoardId();const saved = localStorage.getItem(`deskboard-data-${boardId}`);if (saved){try{const data = JSON.parse(saved);if (data.notes && Array.isArray(data.notes)){notes = data.notes;deletedNotes = data.deletedNotes || [];highestZ = data.highestZ || 10;notes.forEach(note =>{if (note.type === 'timer' && note.timerState){note.timerState.isRunning = false;note.timerState.isPaused = false}if (note.type === 'reminder' && note.reminderState){note.reminderState.isBlinking = false;const now = Date.now();if (note.reminderState.nextTrigger < now){note.reminderState.nextTrigger = now + 5000}}});renderAllNotes();updateBinUI();showToast(`Restored ${notes.length}notes`);return}}catch (e){console.error('Failed to load from storage:',e)}}initDefaultNotes()}function initDefaultNotes(){addNote('sticky',{x:100,y:80,content:"Welcome to DeskBoard! 🎯\n\nDouble-click any note to edit.\nDrag to move around.\nPress N for sticky,T for timer,R for reminder.\n\nKeep this open while you work!"});addNote('reminder',{x:420,y:100});addNote('timer',{x:720,y:100});addNote('checklist',{x:1050,y:100,content:'This Week',items:[{text:'Deploy to production',checked:true},{text:'Write documentation',checked:false},{text:'Team standup prep',checked:false},{text:'Code review backlog',checked:false}]});addNote('quote',{x:200,y:420})}function isStorageAvailable(){try{const test = '__storage_test__';localStorage.setItem(test,test);localStorage.removeItem(test);return true}catch (e){return false}}if (!isStorageAvailable()){showToast('Warning:localStorage unavailable. Data won\'t persist.')}function getBoardList(){try{const list = localStorage.getItem('deskboard-boards');return list ? JSON.parse(list):['default']}catch{return ['default']}}function saveBoardList(list){localStorage.setItem('deskboard-boards',JSON.stringify(list))}function getCurrentBoardId(){return localStorage.getItem('deskboard-current-board') || 'default'}function setCurrentBoardId(id){localStorage.setItem('deskboard-current-board',id)}function loadBoard(boardId){setCurrentBoardId(boardId);notes = [];deletedNotes = [];undoStack = [];redoStack = [];highestZ = 10;selectedNoteId = null;const saved = localStorage.getItem(`deskboard-data-${boardId}`);if (saved){try{const data = JSON.parse(saved);if (data.notes){notes = data.notes;deletedNotes = data.deletedNotes || [];highestZ = data.highestZ || 10;notes.forEach(note =>{if (note.type === 'timer' && note.timerState){note.timerState.isRunning = false;note.timerState.isPaused = false}if (note.type === 'reminder' && note.reminderState){note.reminderState.isBlinking = false;const now = Date.now();if (note.reminderState.nextTrigger < now){note.reminderState.nextTrigger = now + 5000}}});renderAllNotes();updateBinUI();showToast(`Loaded board:${boardId}`);return}}catch (e){console.error('Failed to load board:',e)}}initDefaultNotes()}function saveBoard(boardId){const data ={notes,deletedNotes,highestZ,timestamp:Date.now()};try{localStorage.setItem(`deskboard-data-${boardId}`,JSON.stringify(data))}catch (e){if (e.name === 'QuotaExceededError'){showToast('Storage full! Clear some notes or bin.')}}}function renameBoard(oldId,newId){const list = getBoardList();const idx = list.indexOf(oldId);if (idx !== -1){list[idx] = newId;saveBoardList(list);const data = localStorage.getItem(`deskboard-data-${oldId}`);if (data){localStorage.removeItem(`deskboard-data-${oldId}`);localStorage.setItem(`deskboard-data-${newId}`,data)}if (getCurrentBoardId() === oldId){setCurrentBoardId(newId)}}}function deleteBoard(boardId){const list = getBoardList();if (list.length <= 1){showToast('Cannot delete the last board');return}list.splice(list.indexOf(boardId),1);saveBoardList(list);localStorage.removeItem(`deskboard-data-${boardId}`);if (getCurrentBoardId() === boardId){loadBoard(list[0])}}
function updateBinUI(){const count = deletedNotes.length;binCount.textContent = count > 0 ? `${count}`:'';recycleBin.style.opacity = count > 0 ? '1':'0.7'}function moveToBin(note){const noteWithMeta ={...note,deletedAt:Date.now(),originalId:note.id};deletedNotes.unshift(noteWithMeta);updateBinUI();saveToStorage()}function restoreFromBin(index){const note = deletedNotes[index];if (!note) return;pushHistory();note.id = generateId();note.zIndex = ++highestZ;note.x = Math.max(50,note.x);note.y = Math.max(50,note.y);note.isNew = true;if (note.type === 'timer'){note.timerState ={totalSeconds:note.timerState?.totalSeconds || 25 * 60,remainingSeconds:note.timerState?.totalSeconds || 25 * 60,isRunning:false,isPaused:false,isFinished:false}}if (note.type === 'reminder'){note.reminderState ={...note.reminderState,isBlinking:false,lastAcknowledged:Date.now()}}deletedNotes.splice(index,1);notes.push(note);renderNote(note);updateBinUI();saveToStorage();showToast('Note restored!');playPinSound();setTimeout(() =>{note.isNew = false;const el = document.getElementById(note.id);if (el) el.classList.remove('note-new')},500)}function permanentlyDelete(index){deletedNotes.splice(index,1);updateBinUI();saveToStorage();renderBinModal()}function emptyBin(){if (!confirm(`Permanently delete all ${deletedNotes.length}items? This cannot be undone.`)) return;deletedNotes = [];updateBinUI();saveToStorage();renderBinModal();showToast('Bin emptied')}function openBinModal(){renderBinModal();document.getElementById('binModalOverlay').classList.add('show')}function closeBinModal(event){if (!event || event.target === document.getElementById('binModalOverlay')){document.getElementById('binModalOverlay').classList.remove('show')}}function renderBinModal(){const body = document.getElementById('binModalBody');const total = document.getElementById('binTotal');const emptyBtn = document.getElementById('binEmptyBtn');total.textContent = `${deletedNotes.length}item${deletedNotes.length !== 1 ? 's':''}`;emptyBtn.style.display = deletedNotes.length > 0 ? 'block':'none';if (deletedNotes.length === 0){body.innerHTML = '<div class="bin-empty">No deleted items</div>';return}body.innerHTML = deletedNotes.map((note,index) =>{const typeIcons ={sticky:'📝',paper:'📄',checklist:'☑️',timer:'⏱️',reminder:'⏰',quote:'💬',photo:'🖼️'};const preview = note.type === 'photo' ? '🖼️':(note.content || 'No content').substring(0,30);const timeAgo = getTimeAgo(note.deletedAt);return ` <div class="bin-item"> <div class="bin-item-preview">${typeIcons[note.type] || '📌'}</div> <div class="bin-item-info"> <div class="bin-item-type">${note.type}· ${timeAgo}</div> <div class="bin-item-content">${preview}</div> </div> <div class="bin-item-actions"> <button class="bin-item-btn restore" onclick="restoreFromBin(${index})">Restore</button> <button class="bin-item-btn perm-delete" onclick="permanentlyDelete(${index})">Delete</button> </div> </div> `}).join('')}function checkBinHover(x,y){const binRect = recycleBin.getBoundingClientRect();const isOver = x >= binRect.left && x <= binRect.right && y >= binRect.top && y <= binRect.bottom;recycleBin.classList.toggle('drag-over',isOver);return isOver}
